insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('wellcost', 'intermediate', 'module', 'm01-an-afe-is-a-structure', 1, 'An authority for expenditure is best described as which kind of document?', '["A vendor quotation held on file until the well is spudded.", "A statistical prediction of the final well cost, judged afterwards by how closely the outturn matched the approved figure.", "A request for permission to spend, carrying a number, rather than a prediction of the outcome.", "A contract between the operator and the rig contractor fixing the day rate."]'::jsonb, 2, 'Both documents end in a currency figure and answer to different people, which is why they are so easily confused.'),
  ('wellcost', 'intermediate', 'module', 'm01-an-afe-is-a-structure', 2, 'When is such a document in breach, as opposed to a forecast merely being wrong?', '["When the money approved sits below the amount the costed lines actually bill for the work described.", "Whenever the finished well comes in under the approved figure.", "Whenever the outturn cost differs in either direction from the figure written on it, by any amount a partner would call material.", "When the contingency provision is spent before the well reaches total depth."]'::jsonb, 0, 'Coming in under the authority embarrasses nobody, while going over it means the paperwork must be revisited first.'),
  ('wellcost', 'intermediate', 'module', 'm01-an-afe-is-a-structure', 3, 'Which figure on the golden programme is the one carried forward for approval?', '["The base cost of 5,380,000 USD, signed on its own and topped up later.", "The rig dayrate line of 1,800,000 USD, because it is the largest single commitment anyone on the sheet must fund.", "The contingency provision of 538,000 USD, approved separately from the priced lines.", "The total of 5,918,000 USD, which is the 5,380,000 USD base together with the 538,000 USD provision."]'::jsonb, 3, 'That figure is what the engine returns as totalUsd, and nobody signs the base and finds the remainder afterwards.'),
  ('wellcost', 'intermediate', 'module', 'm01-an-afe-is-a-structure', 4, 'Why is the sheet built as a list of lines instead of one approved value?', '["Because auditors require at least eight entries on any funding request.", "Because only the lines can say which parts of the money keep billing once the well departs from plan.", "Because the partners insist on seeing the named vendor behind each amount before they will release any cash call.", "Because the contingency fraction has to be calculated line by line rather than once."]'::jsonb, 1, 'A total alone is a dead number the moment reality moves, because there is nothing left in it to re-price.'),
  ('wellcost', 'intermediate', 'module', 'm01-an-afe-is-a-structure', 5, 'What does a per-day cost line hold, and what does a lump line hold instead?', '["A per-day line holds a rate to be multiplied, while a lump line holds a value that nothing multiplies.", "Both hold a rate, and the lump line simply applies its rate once.", "A per-day line holds a rate and a day count, while a lump line holds a value and the date on which its invoice falls due.", "A per-day line holds a value and a lump line holds a rate against footage."]'::jsonb, 0, 'Each line also carries an identifier, a readable label, a basis and a category before it carries any money at all.'),
  ('wellcost', 'intermediate', 'module', 'm01-an-afe-is-a-structure', 6, 'What effect does the atActivityId field have on a lump line?', '["It scales the value by the duration of the named activity.", "It moves the amount into the subtotal for the phase the named activity belongs to, which shifts the reported base.", "It sets where the step appears on the cost-time curve and leaves the amount completely unchanged.", "It tells the engine which vendor invoice the line should be reconciled against."]'::jsonb, 2, 'A lump line with no such link is stepped onto the curve at spud, at time zero.'),
  ('wellcost', 'intermediate', 'module', 'm01-an-afe-is-a-structure', 7, 'Why does no cost line store a day count or a depth of its own?', '["So the sheet can be printed without a schedule attached.", "So one line can be priced against any schedule, with days and metres arriving once from outside.", "Because the engine reads the day count from the activity that each line is linked to, rather than from the programme total.", "Because the vendor contract already records the duration, so repeating it would be redundant."]'::jsonb, 1, 'If each line kept its own day count there would be eighteen places to update and eighteen chances to miss one.'),
  ('wellcost', 'intermediate', 'module', 'm01-an-afe-is-a-structure', 8, 'How is contingency applied relative to the individual priced lines?', '["Line by line, at a fraction chosen to suit each individual vendor.", "Only to the per-day lines, since those are the ones a schedule slip can move, leaving the rest untouched.", "To the intangible subtotal alone, because tangible items are already fixed.", "Once, as a fraction of the completed base total, so no individual line carries a provision of its own."]'::jsonb, 3, 'The golden applies a fraction of 0.1 to its base and returns 538,000 USD as a figure of its own.'),
  ('wellcost', 'intermediate', 'module', 'm01-an-afe-is-a-structure', 9, 'What do the five lump lines on the golden reveal about basis and category?', '["That the two are independent, since two of those lump lines are tangible and three are intangible.", "That every lump line on a valid sheet has to be tangible.", "That the basis determines the category, so choosing lump for a line commits it to the tangible subtotal.", "That lump lines are excluded from both of the subtotals."]'::jsonb, 0, 'Casing and accessories and the wellhead are the tangible pair, at 800,000 USD and 250,000 USD.'),
  ('wellcost', 'intermediate', 'module', 'm01-an-afe-is-a-structure', 10, 'What does the basis decide, and what does the category decide?', '["The basis fixes the subtotal and the category fixes the multiplier.", "The basis decides the tax treatment and the category decides whether a schedule slip can move the amount billed.", "The basis decides what the amount is multiplied by, and the category decides which subtotal it lands in.", "Both decide arithmetic, with the category scaling the amount by a fiscal factor."]'::jsonb, 2, 'The engine allows exactly three bases and exactly two categories, and validates both fields on every line.'),
  ('wellcost', 'intermediate', 'module', 'm01-an-afe-is-a-structure', 11, 'How does the engine behave when a line carries a category it cannot recognise?', '["It assigns the line to the intangible subtotal by default.", "It drops the line from the item list entirely and reports a base short by exactly that amount, without warning.", "It keeps the line in the base while quietly omitting it from the cost-time curve.", "It raises an error naming that line, because there is no default value and no silent fallback."]'::jsonb, 3, 'A defaulted category would balance the base while pushing spend into a bucket nobody chose, surfacing months later.'),
  ('wellcost', 'intermediate', 'module', 'm01-an-afe-is-a-structure', 12, 'Which four arguments does the afeCosts function take?', '["The item list, the schedule, the fiscal regime and the currency.", "The item list, a total day count, a drilled length in metres, and a contingency fraction defaulting to zero.", "The item list, the activity programme, the non-productive time fraction and the measured depth reached at total depth.", "The item list, the productive hour count, the measured total depth and the rig day rate."]'::jsonb, 1, 'There is no schedule inside the cost function and no cost inside the schedule function.'),
  ('wellcost', 'intermediate', 'module', 'm01-an-afe-is-a-structure', 13, 'Which day count does the golden hand to its cost run, and why that one?', '["Sixteen days, the productive figure, which the panel also reports.", "Sixteen days, because non-productive hours are absorbed by the contractor and never reach an operator invoice at all.", "Eighteen days, the elapsed figure, because the rig is on hire through non-productive time as well.", "Twenty days, being the elapsed figure rounded upward to leave room for weather delays."]'::jsonb, 2, 'Productive activities take 384 hours and the allowance adds 48, giving 432 elapsed hours.'),
  ('wellcost', 'intermediate', 'module', 'm01-an-afe-is-a-structure', 14, 'What separates drilled metres from the depth the hole reaches?', '["Drilled metres counts the length actually cut, so a sidetrack or a redrill adds to it but not to depth.", "Nothing on any well, since the two are defined identically.", "Drilled metres is measured along hole while total depth is measured vertically, so the two differ on any deviated well.", "Drilled metres excludes the surface hole, which is credited to the mobilisation instead."]'::jsonb, 0, 'On the golden both come to 3,000 m, so the distinction is invisible there and a per-metre line bills on the first.'),
  ('wellcost', 'intermediate', 'module', 'm01-an-afe-is-a-structure', 15, 'Which inputs does the engine refuse outright?', '["A day count above thirty and a drilled length above 5,000 m.", "A negative day count, a negative drilled length, a negative contingency fraction, or items that are not an array.", "A contingency fraction above one, together with any line whose rate exceeds the largest lump value carried.", "A lump line carrying no activity link, because the curve would have nowhere to place it."]'::jsonb, 1, 'It also rejects a negative rate or a negative value inside a line, which would describe a rig that pays you.'),
  ('wellcost', 'intermediate', 'module', 'm02-the-three-cost-bases', 1, 'How does the engine price the golden rig dayrate line?', '["It reads a stored value of 1,800,000 USD straight off the line.", "It multiplies the 100,000 USD daily rate by the eighteen day count, giving 1,800,000 USD.", "It multiplies the daily rate by the 384 productive hours and then divides that product by twenty four.", "It multiplies the daily rate by the drilled length of 3,000 m."]'::jsonb, 1, 'A per-day line carries a rate and nothing else, so the day count has to arrive from the schedule.'),
  ('wellcost', 'intermediate', 'module', 'm02-the-three-cost-bases', 2, 'What do the two per-day rates on the golden add up to?', '["They come to 100,000 USD, since only the rig is on a daily hire.", "They come to 250,000 USD, being the rig plus the wellhead value spread across the eighteen days.", "They come to 60,000 USD, because the spread absorbs the rig hire under an integrated contract.", "They come to 160,000 USD, which is what a single calendar day of this well costs before contingency."]'::jsonb, 3, 'The rig sits at 100,000 USD per day and the integrated services spread at 60,000 USD per day.'),
  ('wellcost', 'intermediate', 'module', 'm02-the-three-cost-bases', 3, 'What share of the golden base is billed on a daily hire?', '["Just over half, at 2,880,000 USD of the base, which works out at 53.53 percent of the sheet.", "Roughly a twelfth, at 450,000 USD of the base.", "Roughly two fifths, at 2,050,000 USD of the base, since the five fixed price jobs dominate the sheet.", "Roughly four fifths, at 4,330,000 USD, which is the consumed share of the well."]'::jsonb, 0, 'Per-metre lines take 8.36 percent and lump lines 38.10 percent of the same 5,380,000 USD base.'),
  ('wellcost', 'intermediate', 'module', 'm02-the-three-cost-bases', 4, 'What shape does a daily hire line trace on the cost-time curve?', '["A vertical step at the end of the activity it names.", "A slope while making hole and a horizontal segment during trips, casing runs and flat time on location.", "A constant slope with no flat segments at all, holding the same gradient whatever the hole is doing.", "A curve that steepens as measured depth increases and the rate of penetration falls."]'::jsonb, 2, 'That is why a well which stops making hole carries on making cost at the same gradient as before.'),
  ('wellcost', 'intermediate', 'module', 'm02-the-three-cost-bases', 5, 'What is the test for putting a vendor on a daily hire basis?', '["Ask whether the vendor is present on location for more than a week.", "Ask whether the amount involved is large enough to appear among the top three rows of the sorted sheet.", "Ask whether the vendor supplies people rather than delivered hardware.", "Ask whether the invoice arrives whether or not the well made any hole on the day in question."]'::jsonb, 3, 'You are paying for availability rather than for a quantity delivered, which is what the basis records.'),
  ('wellcost', 'intermediate', 'module', 'm02-the-three-cost-bases', 6, 'A one-off job happens to occupy three days on location. Which basis suits it?', '["Per-day, because the work occupied three days of rig time.", "Lump, since you are buying the finished job rather than the days, and an overrun falls on the vendor.", "Per-metre, because any job performed downhole consumes hole and therefore scales with the interval drilled.", "Per-day for the first day and lump for the remainder of the work."]'::jsonb, 1, 'A duration attached to such a job lives in the schedule, never on the cost line itself.'),
  ('wellcost', 'intermediate', 'module', 'm02-the-three-cost-bases', 7, 'How does the golden price its mud and consumables line?', '["At 150 USD per metre over the eighteen days of elapsed time.", "At 770 USD per metre over the production section, taken from the worked example carried in this course.", "At 150 USD per metre over 3,000 m of drilled length, which comes to 450,000 USD on this well.", "At 600 USD per metre, calibrated so that it matches the rig line on the base case."]'::jsonb, 2, 'That makes it the smallest of the three bases here by a wide margin, at 8.36 percent of the base.'),
  ('wellcost', 'intermediate', 'module', 'm02-the-three-cost-bases', 8, 'Hold the hole at total depth and stretch the schedule. What happens to a footage line?', '["It does not move at all, because none of the added time consumes another metre of hole.", "It rises in step with the elapsed day count, as every priced line does.", "It rises, though more slowly than a daily hire line, because circulating hours are billed at a reduced footage rate.", "It falls, since the same footage is now spread across a longer period."]'::jsonb, 0, 'That inertness with respect to time is the property which makes the basis worth choosing deliberately.'),
  ('wellcost', 'intermediate', 'module', 'm02-the-three-cost-bases', 9, 'Where does a footage line go flat on the cost-time curve?', '["Only at spud, before any activity has started.", "Nowhere at all, since consumables continue to be drawn down at a steady rate for as long as the well lasts.", "At every point where a fixed price step lands on the curve.", "During trips, casing runs and flat time, because no drilled length is being added in those periods."]'::jsonb, 3, 'Its contribution therefore has the same shape as the depth curve, sloped while making hole and flat otherwise.'),
  ('wellcost', 'intermediate', 'module', 'm02-the-three-cost-bases', 10, 'What is the honest limit of pricing mud against footage?', '["The rate has to be recalculated after every hole section.", "Real consumption is not purely footage driven, so circulating for days without drilling burns unseen chemicals.", "Mud volumes are measured in barrels rather than metres, so the basis cannot be dimensionally correct at all.", "Footage pricing understates the cost of the surface hole and overstates the production hole."]'::jsonb, 1, 'Splitting the vendor across two bases would buy a little accuracy and cost a lot of clarity on a sheet meant to be signed.'),
  ('wellcost', 'intermediate', 'module', 'm02-the-three-cost-bases', 11, 'What do the five fixed price lines on the golden come to, and what moves them?', '["They come to 2,050,000 USD, and re-linking one to a later activity leaves the base entirely unchanged.", "They come to 2,880,000 USD, and a schedule slip lifts them.", "They come to 2,050,000 USD, and moving one to a later activity raises the base because the money is committed later.", "They come to 450,000 USD, and deepening the hole lifts them in proportion."]'::jsonb, 0, 'That is 38.10 percent of the base, and the activity link decides only when the step appears on the curve.'),
  ('wellcost', 'intermediate', 'module', 'm02-the-three-cost-bases', 12, 'A mobilisation gets the rig to location for an agreed price. Which basis applies?', '["Per-day, priced across the days the tow actually takes.", "Per-metre, because mobilisation cost scales with the depth the resulting well is planned to reach.", "Lump, and it usually names no activity, so the engine steps the whole amount onto the curve at spud.", "Lump, but it must always name an activity so the step can be placed."]'::jsonb, 2, 'If the tow runs two days long that exposure sits with the contractor rather than with the operator.'),
  ('wellcost', 'intermediate', 'module', 'm02-the-three-cost-bases', 13, 'How should a bit supplier be treated on the sheet?', '["Always per-day, because bits are consumed while the rig turns.", "Either way, since a footage contract sells metres while a bit bought outright is a purchase and so lump.", "Always per-metre, since the whole point of a bit is the footage it delivers before it is pulled and replaced.", "Always lump, because the supplier quotes a fixed price for the run."]'::jsonb, 1, 'The 50,000 USD bit in this course sits inside a standalone worked example rather than in the reference programme.'),
  ('wellcost', 'intermediate', 'module', 'm02-the-three-cost-bases', 14, 'Calibrate 1,800,000 USD three ways on the base case and then slip the schedule to 24 days. What happens?', '["The daily hire line reaches 2,400,000 USD while the footage and fixed price versions stay where they were.", "All three rise together, since they were calibrated to agree.", "The footage version rises to 2,400,000 USD while the daily hire version holds at its original calibrated amount.", "All three hold flat, because the hole is still at the same depth."]'::jsonb, 0, 'Elasticity to elapsed days measures 1 for the daily hire basis and exactly 0 for the other two.'),
  ('wellcost', 'intermediate', 'module', 'm02-the-three-cost-bases', 15, 'Take the same three calibrations to 4,000 m instead. Which one moves fastest?', '["The daily hire version, because deeper holes take proportionally longer.", "The fixed price version, since a deepening is treated as a variation and is repriced at the agreed unit rate.", "The footage version, at 2,400,000 USD against 2,303,125 USD for the version priced on a daily hire.", "Neither of them, because both are calibrated to the same base case."]'::jsonb, 2, 'Extra metres add drilling hours only, while the day count also carries flat time that does not grow with depth.'),
  ('wellcost', 'intermediate', 'module', 'm03-tangible-and-intangible', 1, 'How does the engine produce the two subtotals from one item list?', '["It runs the item list twice, once per category, and adds the two passes together.", "It derives them from the basis, sending fixed price lines to one subtotal and everything else to the other.", "It splits each line in proportion to the salvage value the operator expects to recover.", "It prices every line once and then sums the amounts twice, sorting each amount by the category it carries."]'::jsonb, 3, 'Every line carries a category and no line carries two, so the two subtotals add back to the base exactly.'),
  ('wellcost', 'intermediate', 'module', 'm03-tangible-and-intangible', 2, 'What are the two category fractions on the golden well?', '["They are close to even, at 53.53 percent against 46.47 percent.", "Around a fifth is tangible at 19.52 percent, leaving 80.48 percent of the base as intangible.", "Around a third is tangible at 38.10 percent, that being the share of the base carried on fixed price lines.", "Around a twelfth is tangible at 8.36 percent of the base."]'::jsonb, 1, 'In money those fractions are 1,050,000 USD and 4,330,000 USD of a 5,380,000 USD base.'),
  ('wellcost', 'intermediate', 'module', 'm03-tangible-and-intangible', 3, 'Which of the eight golden lines end up in the tangible column?', '["The rig dayrate and the integrated services spread.", "Casing and accessories together with completion services, since both leave hardware behind in the finished well.", "Casing and accessories at 800,000 USD and the wellhead at 250,000 USD, both of them fixed price lines.", "The cementing job, the wireline run and the wellhead."]'::jsonb, 2, 'The remaining six lines are intangible and between them they span all three of the cost bases.'),
  ('wellcost', 'intermediate', 'module', 'm03-tangible-and-intangible', 4, 'Where does the contingency provision sit relative to the two category subtotals?', '["Outside both of them, computed as a fraction of the base once the two sums are already complete.", "Inside the intangible subtotal, since a provision buys no asset.", "Split between them in proportion to their shares, so that the provision matches the shape of the sheet it protects.", "Inside the tangible subtotal, because unplanned work usually means extra steel."]'::jsonb, 0, 'Nobody knows in advance whether the provision will buy steel or buy days, so classifying it early would be a guess.'),
  ('wellcost', 'intermediate', 'module', 'm03-tangible-and-intangible', 5, 'Recategorise the wellhead and rerun the sheet. Which figures respond?', '["Every figure on the sheet moves, since the base is rebuilt from the categories.", "Only the two subtotals, shifting by 250,000 USD each in opposite directions while three figures hold still.", "The base and the total both move by 250,000 USD, because the wellhead amount has been reassigned to another bucket.", "Nothing moves at all, because the engine ignores the category field."]'::jsonb, 1, 'The base, the provision and the approval total are untouched, so the split is invisible to the authority requested.'),
  ('wellcost', 'intermediate', 'module', 'm03-tangible-and-intangible', 6, 'Which question settles whether a cost is tangible or intangible?', '["Was the amount agreed in advance or billed against actual usage?", "Did the spend occur before the well was spudded or after it, since only the later spend can leave an asset behind?", "Does the line appear above or below the provision in the sorted sheet?", "At the end of the well, is anything durable still down there with salvage value left in it?"]'::jsonb, 3, 'The test is asked of the object rather than of the invoice, so the payment terms are irrelevant to it.'),
  ('wellcost', 'intermediate', 'module', 'm03-tangible-and-intangible', 7, 'Why does the way you paid for something tell you nothing about its category?', '["Because the question is whether anything durable survives the job, not whether the price was fixed or metered.", "Because the payment terms are held on the contract, not the line.", "Because the engine validates the basis first and the category afterwards, so the two fields cannot influence each other.", "Because most vendors bill on more than one basis across a single well."]'::jsonb, 0, 'Drill pipe bought on a footage contract would be priced per metre and still be tangible, since the pipe survives.'),
  ('wellcost', 'intermediate', 'module', 'm03-tangible-and-intangible', 8, 'Why do completion services and completion hardware fall on opposite sides?', '["Because hardware is bought as a lump and services are bought per day.", "Because the hardware is delivered before spud while the services are performed afterwards, and timing decides the split.", "The packers, tubing and screens stay in the hole, while the labour and pumping that installed them do not.", "Because only the hardware attracts a salvage charge at abandonment."]'::jsonb, 2, 'A real sheet splits that vendor across two lines, and the golden carries only the services half of it.'),
  ('wellcost', 'intermediate', 'module', 'm03-tangible-and-intangible', 9, 'What does a line being on a fixed price basis tell you about its category?', '["That it must be tangible, because a fixed price buys a thing.", "Nothing at all, since three of the five fixed price lines on this sheet are intangible rather than tangible.", "That it must be intangible, because a fixed price covers a job performed rather than an item delivered.", "That it is tangible whenever the line also names an activity on the curve."]'::jsonb, 1, 'The reverse shortcut fails as well, because a per metre purchase of durable equipment would still be tangible.'),
  ('wellcost', 'intermediate', 'module', 'm03-tangible-and-intangible', 10, 'Steel is set in the hole and later milled out. How was it classified when bought?', '["As intangible, because nothing durable survived to the end.", "As tangible until the milling run, after which the engine moves the amount across into the other subtotal automatically.", "As a provision, since the possibility of milling was unplanned work.", "As tangible, because the category records what the spend acquired rather than what later became of it."]'::jsonb, 3, 'Salvage value is judged at the point of purchase, which keeps the classification stable across the life of the well.'),
  ('wellcost', 'intermediate', 'module', 'm03-tangible-and-intangible', 11, 'Why is the split on the form at all, given that it moves no figure on the sheet?', '["Because partners use it to allocate the cash call between them.", "Because the engine needs it to place the fixed price steps correctly along the cost-time curve for cash flow work.", "Because the two categories are recovered differently for tax, one capitalised over years and one relieved sooner.", "Because insurers price cover against the tangible column alone."]'::jsonb, 2, 'The engine holds no tax rates and models none of that, it only sorts lines into the two buckets asked for downstream.'),
  ('wellcost', 'intermediate', 'module', 'm03-tangible-and-intangible', 12, 'Who reads the two subtotals rather than the base and the total?', '["The finance and tax functions, whose calculation cannot begin until the base has been partitioned in two.", "The drilling engineer, who plans the programme around them.", "The rig contractor, who invoices against whichever of the two subtotals covers the services actually delivered.", "Nobody in practice, since the subtotals are printed for completeness only."]'::jsonb, 0, 'Joint venture partners read all four, because a cash call goes against the total while their books need the split.'),
  ('wellcost', 'intermediate', 'module', 'm03-tangible-and-intangible', 13, 'Sort the golden rows by amount. Where does the provision fall, and what sits above it?', '["Last, below every contracted line on the sheet.", "Fourth, under two daily hire lines and the casing, so it outranks five of the eight contracted lines.", "First, above the rig dayrate, because a provision covers work that has not yet been defined or priced anywhere.", "Second, immediately under the rig dayrate line."]'::jsonb, 1, 'The top three rows come to 3,680,000 USD of the base, and the largest alone is 33.46 percent of it.'),
  ('wellcost', 'intermediate', 'module', 'm03-tangible-and-intangible', 14, 'What does an amount ordering deliberately destroy?', '["The category grouping and the timing, since tangible rows are interleaved and no row hints at when it lands.", "The link between each line and the vendor supplying it.", "The distinction between the base and the approval total, which is why the provision has to be listed as a row of its own.", "The arithmetic, because sorted amounts no longer add back to the base."]'::jsonb, 0, 'The wellhead lands early on the curve and the completion lands last, yet the sorted rows sit four apart with no sign of it.'),
  ('wellcost', 'intermediate', 'module', 'm03-tangible-and-intangible', 15, 'Why is a high intangible share not evidence that a well was run badly?', '["Because the share is fixed by the fiscal regime rather than by the operator.", "Because the intangible column always exceeds the tangible column by construction, on every well ever drilled anywhere.", "Because a well is a hole, and the dominant cost of making one leaves nothing behind that anyone could sell.", "Because the two columns are compared only after contingency is added."]'::jsonb, 2, 'Raising the ratio means buying steel the well does not need, or buying fewer days, which is worth doing for the 160,000 USD a day.'),
  ('wellcost', 'intermediate', 'module', 'm04-contingency', 1, 'A reviewer asks which activity the contingency on the golden AFE is priced against. What is the answer?', '["It is priced against nothing at all, because contingency carries no basis, no category and no activity.", "It is priced against the completion and handover activity.", "It is spread across the eight priced lines in proportion to the amount each of them contributes to the base cost of the well.", "It is priced against the longest drilling activity, which is where most of the uncertainty sits."]'::jsonb, 0, 'The engine takes contingencyFrac as a single number beside the item list, and no item in that list is the contingency.'),
  ('wellcost', 'intermediate', 'module', 'm04-contingency', 2, 'Working the golden estimate, what does a fraction of 0.1 produce against a base of 5,380,000 USD?', '["A provision of 538,000 USD and a total that stays at 5,380,000 USD.", "A provision of 591,800 USD, because the fraction is taken against the figure the estimate finally goes forward with for approval.", "A provision of 538,000 USD and an approved total of 5,918,000 USD, being the base plus that provision.", "A provision of 433,000 USD, from applying the fraction to the intangible items only."]'::jsonb, 2, 'Nobody will invoice that 538,000 USD. If the well goes to plan it is never spent, and it was still right to carry it.'),
  ('wellcost', 'intermediate', 'module', 'm04-contingency', 3, 'An estimate carries ten percent contingency on the base. What share of the approved total is that provision?', '["0.1 of the total, since the fraction reads the same against either figure.", "0.09090909090909091 of the total, because the base grew by the very amount you are taking a share of.", "0.11111111111111111 of the total, the same figure the non-productive time allowance reaches on the golden schedule.", "0.05 of the total, because a provision is halved when it is read against the larger denominator."]'::jsonb, 1, 'Read a stated percentage off the total and you are crediting the estimate with a smaller provision than was actually made.'),
  ('wellcost', 'intermediate', 'module', 'm04-contingency', 4, 'A partner proposes a contingency fraction of 0.5 on the base. What fraction of the approved total does that reach?', '["0.5 of the total, because half of the base is half of everything.", "0.6666666666666666 of the total, because the provision lands once on the tangible items and once on the intangible ones.", "0.25 of the total, which is the value the published sweep records at a fraction of 0.25.", "0.3333333333333333 of the total, since a fraction f on the base is f/(1+f) once the total is formed."]'::jsonb, 3, 'The same stretch arithmetic governs the non-productive time allowance in the tier below, and it catches people the same way.'),
  ('wellcost', 'intermediate', 'module', 'm04-contingency', 5, 'In the engine''s order of work, at which point does the contingency fraction enter?', '["Between the schedule and the pricing, so that each rate already includes it.", "After the items are priced and summed into tangible and intangible, with only the total left to form.", "At the same moment the per day lines are priced, because both of them depend on the elapsed days the schedule produced.", "Before any item is priced, so that every line on the form carries it separately."]'::jsonb, 1, 'Nothing downstream of the fraction exists except the total, and the engine never doubles back to reprice a line.'),
  ('wellcost', 'intermediate', 'module', 'm04-contingency', 6, 'The golden AFE carries 800,000 USD of casing and a 250,000 USD wellhead, both on firm purchase orders. How does the fraction treat them?', '["It lands on them at the same ten percent as everything else, because one fraction is applied flat.", "It leaves them out, since a firm quote needs no provision.", "It applies a reduced fraction to tangible items, on the argument that steel bought against a purchase order is already fixed.", "It reaches them only once the completion and handover activity has been priced and closed."]'::jsonb, 0, 'A ten percent provision on a firm steel quote is a strange thing to defend, and the model makes no attempt to defend it.'),
  ('wellcost', 'intermediate', 'module', 'm04-contingency', 7, 'A colleague reads the tangible share of 0.19516728624535315 and asks which denominator produced it. What do you tell them?', '["The approved total, which is the figure every share on the form is quoted on.", "The base plus half the contingency, on the reasoning that a provision is split between the two categories in proportion.", "The sum of the lump items only, which is what the split is computed over.", "The base, because the category shares leave the provision out and the two of them add exactly to one."]'::jsonb, 3, 'An AFE carries two different denominators on the same page, so read any percentage and ask which one it used.'),
  ('wellcost', 'intermediate', 'module', 'm04-contingency', 8, 'Raise the non-productive allowance to 0.5 and the golden base becomes 6,340,000 USD. What happens to the provision?', '["It holds at 538,000 USD, which is what a provision is for.", "It falls to 506,000 USD, because a longer schedule leaves less of the estimate exposed to any further uncertainty at all.", "It grows to 634,000 USD, so the provision meant to absorb the slip has ridden up on it instead.", "It grows to 960,000 USD, the amount by which the base has moved above the golden figure."]'::jsonb, 2, 'The base moved 960,000 USD and the provision moved 96,000 USD with it, which is a property of a percentage.'),
  ('wellcost', 'intermediate', 'module', 'm04-contingency', 9, 'At the reference fraction of 0.1, how does the 538,000 USD provision measure against the largest committed line?', '["It reaches half the rig dayrate and ranks second of the nine.", "It reaches 0.29888888888888887 of the rig dayrate but is left out of any ranking, since a provision is not a priced line.", "It reaches 0.29888888888888887 of the rig dayrate and ranks fourth of the nine numbers shown.", "It reaches 0.1 of the rig dayrate, because the fraction applies to each line separately."]'::jsonb, 2, 'Eight of those nine numbers are somebody''s contract and one is not, and the one that is not sits above completion services.'),
  ('wellcost', 'intermediate', 'module', 'm04-contingency', 10, 'State the general condition under which a provision overtakes a contracted line of amount L.', '["The fraction must exceed the ratio of L to the largest line on the page.", "The fraction must exceed L divided by the base, which is that line''s own share of the estimate.", "The fraction must exceed twice L over the base, because the base itself grows when the provision is added to it at the end.", "The fraction must exceed L divided by the approved total rather than by the base."]'::jsonb, 1, 'On a well whose largest contract is a third of the estimate, a third is all it takes for the provision to pass it.'),
  ('wellcost', 'intermediate', 'module', 'm04-contingency', 11, 'Bisecting the engine output gives 0.33457249070631967 and the ratio gives 0.3345724907063197. Why does that matter?', '["Agreement to machine precision shows the crossing is a property of the model and not of the search.", "It shows only that the bisection was run for enough iterations.", "The small difference between them is the rounding the engine introduces, and it sets the accuracy of any AFE built on it.", "It shows the rig dayrate is the largest line, which the sort had already established."]'::jsonb, 0, 'Solving f times base equals L is exactly what the bisection does, so any real gap between the two would be a bug.'),
  ('wellcost', 'intermediate', 'module', 'm04-contingency', 12, 'At what fraction does the provision pass the 1,080,000 USD integrated services spread?', '["0.20074349442379186 less the tangible share of the base.", "0.3345724907063197, the same fraction that carries the provision past the rig dayrate, because the two crossings coincide.", "0.15, at which the published ladder already records the provision in third place.", "0.20074349442379186, which is simply that line divided by the 5,380,000 USD base and nothing more."]'::jsonb, 3, 'The ladder puts the provision third at 0.15 and second at 0.25, so the pass happens between those two rows.'),
  ('wellcost', 'intermediate', 'module', 'm04-contingency', 13, 'An operator whose standard fraction is 0.4 applies it to this estimate. What does the sorted page then look like?', '["The provision is 2,152,000 USD and the largest single number on the well, ahead of the rig dayrate.", "The provision reaches 2,152,000 USD and still ranks second.", "The provision is 1,614,000 USD and ranks third, because a fraction of that size cannot pass any of the contracted lines.", "The provision is 2,690,000 USD, which is a third of what finally gets approved."]'::jsonb, 0, 'Between zero and a half the provision climbs from last place to first, and it takes third place at 0.15 already.'),
  ('wellcost', 'intermediate', 'module', 'm04-contingency', 14, 'Asked how likely 5,918,000 USD is to be enough, what can the golden estimate honestly say?', '["That it is by construction the most likely outcome of the well.", "That it is a P50, because a base built from most likely inputs sits in the middle of the outcome distribution.", "Nothing, because a single figure carries no probability and no input in it describes how wrong it is.", "That the probability is 0.9, which is the usual reading of a ten percent provision."]'::jsonb, 2, 'Ask why the fraction is 0.1 and the honest answers are precedent, the last well, or a corporate standard.'),
  ('wellcost', 'intermediate', 'module', 'm04-contingency', 15, 'Which change to the inputs would let somebody answer that question with a percentile?', '["Raising the fraction until the total looks safe enough to sign.", "Replacing the four single point inputs with ranges and drawing them repeatedly against a fixed seed.", "Averaging the two rates of penetration, since the mean of a rate carries straight through into the mean of the cost.", "Splitting the provision across the eight priced lines in proportion to their size."]'::jsonb, 1, 'Time goes as one over the rate of penetration, so two of the four uncertain inputs do not average through to the cost.'),
  ('wellcost', 'intermediate', 'module', 'm05-cost-per-metre', 1, 'What sits above and below the line in the cost per metre form the engine implements?', '["A bit cost plus a rig rate times the summed hours, all of it divided by the interval drilled.", "A rig rate times the elapsed days, divided by the section total depth.", "A bit cost plus a rig rate times the drilling hours only, divided by the metres the whole well eventually reached.", "A sum of every AFE line attached to the section, divided by the metres that section made."]'::jsonb, 0, 'Only three of the six inputs are hours, and they enter as one bracket, so the form cannot tell them apart afterwards.'),
  ('wellcost', 'intermediate', 'module', 'm05-cost-per-metre', 2, 'Why does the engine refuse an interval of zero rather than returning a very large number?', '["Because a zero interval would make the bit cost negative.", "Because the guard is inherited from the schedule builder, where an activity of zero duration is also rejected.", "The division has no meaning for a section that made no hole, however much that section cost.", "Because the rig rate would then have to be quoted per day rather than per hour."]'::jsonb, 2, 'Every other input may be zero or more. A flat spot has a cost and no rate, and the engine says so by refusing.'),
  ('wellcost', 'intermediate', 'module', 'm05-cost-per-metre', 3, 'Reproduce the published worked example: a 50,000 USD bit, 6,000 USD/hr rig, 100 drilling, 4 connection and 16 trip hours over 1,000 m.', '["650 USD/m, taken from the bit and the drilling hours alone.", "770 USD/m, since the rig is paid for 120 hours and the bit is carried by the same thousand metres.", "720 USD/m, because a bit is a capital item and belongs outside the numerator, which leaves the rig hours to divide.", "12,050 USD/m, which is what dividing by the 100 drilling hours rather than the interval produces."]'::jsonb, 1, 'The published figure is reproduced with an absolute error of zero, which is what makes it usable as a fixture.'),
  ('wellcost', 'intermediate', 'module', 'm05-cost-per-metre', 4, 'A report quotes 770 USD/m beside the golden well''s schedule. Which detail proves that rate belongs to no section of this well?', '["Its bit cost of 50,000 USD, which no section of this well uses.", "Its rig rate of 6,000 USD/hr, which is far above the 100,000 USD per day the golden estimate carries for the rig.", "Its interval of 1,000 m, because no section of this well drilled exactly a thousand metres.", "Its 16 hour trip, when the deepest trip in this schedule is the 12 productive hours at total depth."]'::jsonb, 3, 'The trip at 2,000 m takes 8 hours and the one at total depth takes 12, so no schedule entry can supply 16.'),
  ('wellcost', 'intermediate', 'module', 'm05-cost-per-metre', 5, 'An engineer needs the production hole''s cost per metre and reaches for the 770 USD/m fixture. What should be done instead?', '["Scale 770 USD/m by the ratio of the two intervals.", "Build it from that section''s own hours and its own interval, which give 746 USD/m rather than 770.", "Quote 770 USD/m with a note that it is indicative, since the two sections are drilled by the same rig at the same rate.", "Take the whole well figure of 1793.3333333333333 USD/m, which already includes the production hole."]'::jsonb, 1, 'A rate you cannot trace to an interval and three hour terms is a rate nobody can check, whatever its provenance.'),
  ('wellcost', 'intermediate', 'module', 'm05-cost-per-metre', 6, 'On the published fixture the rig is 0.935064935064935 of the rate and the bit 0.06493506493506493. What does that ratio argue?', '["That the bit cost should be left out of the form entirely.", "That the rig rate should be renegotiated before any bit selection work is attempted, because it dominates the outcome.", "That a bit is worth buying for the hours it saves, since its own price barely moves the number.", "That the connection allowance is the term most worth arguing about on a deep section."]'::jsonb, 2, 'The bit share is 0.24271844660194175 on the surface section and 0.06702412868632708 on the production hole.'),
  ('wellcost', 'intermediate', 'module', 'm05-cost-per-metre', 7, 'Where do the drilling hours in the form come from, and what do they give on the three golden sections?', '["The interval over the rate of penetration, giving 20, 100 and 100 productive hours in that order.", "The elapsed days of the section multiplied by 24.", "The stretched hours the schedule reports, which are 22.5, 112.5 and 112.5 once the allowance has been applied to them.", "The trip speed divided into the section depth, giving 2, 8 and 12 hours across the three."]'::jsonb, 0, 'Rotating time totals 220 hours of the 432 elapsed, which is 0.5729166666666666 of the schedule.'),
  ('wellcost', 'intermediate', 'module', 'm05-cost-per-metre', 8, 'The section pricing allows 4 connection hours per section flat. On which of the golden sections does that allowance matter most?', '["The production hole, because it is the deepest and most expensive.", "The intermediate hole, since it drills the longest interval and therefore makes by far the greatest number of connections.", "None of them, because a flat allowance affects every section in the same proportion.", "The surface hole, where 4 hours is a fifth of its 20 drilling hours rather than a twenty fifth."]'::jsonb, 3, 'The allowance is a modelling choice rather than a measurement, and it is the term people are most casual about.'),
  ('wellcost', 'intermediate', 'module', 'm05-cost-per-metre', 9, 'How are the trip hours in the golden sections derived, and what do they come to at 2,000 m and at total depth?', '["Depth over the trip speed, giving 4 hours and 6 hours.", "The casing running speed applied to the same depths, which gives 5 hours at 2,000 m and 10 hours at total depth.", "Twice the depth over a 500 m/hr trip speed, which gives 8 hours and then 12 hours respectively.", "A flat 16 hours at every depth, taken from the published worked example."]'::jsonb, 2, 'The round trip factor of 2 holds at every depth, so a trip costs 4 hours per thousand metres at that speed.'),
  ('wellcost', 'intermediate', 'module', 'm05-cost-per-metre', 10, 'The surface section is given 2 trip hours although the programme runs 20 inch casing straight after drilling. What is that hour?', '["A short wiper trip that the schedule prices separately.", "A synthetic term, added so the three sections can be compared on the same form, and flagged as such.", "The running time for the 20 inch casing, which the section pricing charges as a trip because the two are alike.", "An allowance for the rig move, apportioned to the first section that drills."]'::jsonb, 1, 'Two hours at 6,000 USD/hr is 12,000 USD on a 206,000 USD section, so it changes no conclusion and should still be declared.'),
  ('wellcost', 'intermediate', 'module', 'm05-cost-per-metre', 11, 'A section rate is compared directly against a rig line on the AFE. Which clock does each of them use?', '["The rate counts productive hours only, while the AFE line is billed against elapsed days including slippage.", "Both count elapsed time, so the comparison is sound.", "The rate counts elapsed hours and the AFE line counts productive days, which is why the rate is the larger figure.", "Both count productive time, since the allowance is applied after the estimate is complete."]'::jsonb, 0, 'The allowance stretches productive time by 12.5 percent on this well and is 0.1111111111111111 of elapsed time.'),
  ('wellcost', 'intermediate', 'module', 'm05-cost-per-metre', 12, 'Somebody divides the production section cost by 3,000 m instead of 1,000 m. What does the output do?', '["It errors, because the engine checks the interval against the schedule.", "It reports three times the true rate, since dividing by a larger number in this form raises the reported cost per metre.", "It reports the correct rate, because the whole well drilled 3,000 m in any case.", "It reports a third of the true rate, and nothing in the run errors or flags the substitution."]'::jsonb, 3, 'The trap flatters the deepest and dearest section most, which is usually the one being defended.'),
  ('wellcost', 'intermediate', 'module', 'm05-cost-per-metre', 13, 'Why does substituting section total depth for interval stay hidden at whole well level on this particular programme?', '["Because the engine reconciles the two figures before dividing.", "The well starts at surface and drilled every metre of its hole, so both denominators come to 3,000 m.", "Because the surface section is short enough that any difference between the two is lost in the rounding of the output.", "Because the whole well rate is quoted against the total rather than the base, which absorbs the difference."]'::jsonb, 1, 'Put a sidetrack, a re-entry or a tie-back in front of the same programme and the two denominators part at once.'),
  ('wellcost', 'intermediate', 'module', 'm05-cost-per-metre', 14, 'Sweeping the intermediate section''s rate of penetration against a fixed production hole, where do the two rankings disagree?', '["Below 9.027081243731192 m/hr, where the section is slowest.", "Above 14.423076923076923 m/hr, because a faster section always spreads its fixed costs over more metres per hour worked.", "Between 9.027081243731192 and 14.423076923076923 m/hr, where it costs less per metre and more in total.", "Nowhere, because a section that costs more in total always costs more per metre."]'::jsonb, 2, 'The golden drills that section at 15 m/hr, so slowing it by a little over half a metre per hour would part the two rankings.'),
  ('wellcost', 'intermediate', 'module', 'm05-cost-per-metre', 15, 'Two wells report identical cost per metre on every section. What can that comparison support?', '["Very little, since the three golden sections are only 0.31115241635687735 of the AFE base cost.", "Nothing at all, because rates are never comparable between wells.", "A full comparison of the two wells, provided both used the same rig rate and the same bit price in the calculation.", "A comparison of their casing and completion scopes, which the section rates carry implicitly."]'::jsonb, 0, 'Casing, cement, the wellhead, logging, mud, completion, the rig move and every non-productive hour sit outside the form.'),
  ('wellcost', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'A new starter asks how you decide, line by line, whether a number on the sheet will move when the well does. What do you tell her?', '["Watch the size of the line, since a big line always moves most.", "Every line is a rate times an exposure, and the exposure is a day, a metre, or nothing at all.", "Look at whether the vendor is on a contract, because contracted work is fixed and everything else on the sheet floats.", "Check the category, because tangible lines are fixed and intangible lines follow the well."]'::jsonb, 1, 'Most review arguments are about a rate when the disagreement is really about the days or the metres behind it.'),
  ('wellcost', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'A planner has begun pricing the rig line while the activity programme is still being argued over. Why does that not work?', '["Because the rig rate is not agreed until the programme is signed.", "Because a per day line has to be converted to a lump before pricing, and the conversion needs a finished duration for it.", "Because pricing must begin with the tangible lines and the rig is intangible.", "Elapsed days and metres drilled come out of the schedule, so nothing can be priced until it settles."]'::jsonb, 3, 'The order of work is not negotiable, since each step consumes the output of the one before it.'),
  ('wellcost', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'A reviewer prices the rig dayrate on productive days by mistake, then runs all four closing checks. What happens?', '["Every check passes, because the arithmetic stays consistent even though the day count used was wrong.", "The category check fails, since the rig is an intangible line.", "The contingency check fails, because a smaller base makes the provision fall short of the fraction that was typed in.", "The cost per metre check fails, since it draws its hours from the same schedule."]'::jsonb, 0, 'Only a comparison of the day count against the schedule''s own elapsed days catches this one, and it understates every rig and spread line at once.'),
  ('wellcost', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'An analyst''s sheet shows tangible and intangible subtotals that do not sum to the base he has reported. What does that indicate?', '["A rounding difference, which is normal on a sheet of this size.", "The provision, which sits inside the base and is therefore missing from the two category subtotals he has listed.", "A line has been counted twice, or a line carries a category the engine does not recognise at all.", "A per day line priced on the wrong day count, which shifts one subtotal only."]'::jsonb, 2, 'On the golden sheet 1,050,000 plus 4,330,000 comes to 5,380,000 USD, and the check is meant to be exact.'),
  ('wellcost', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'A reviewer subtracts the base from the approved total and gets slightly more than the stated provision. How should he read that?', '["As an error, since the difference has to be the fraction times the base and nothing else besides.", "As acceptable, provided the gap is under one percent of the base.", "As the escalation the engine applies to the provision, which is why the difference always runs a little above the stated figure.", "As proof the fraction was applied to the intangible subtotal only."]'::jsonb, 0, 'On the golden sheet 5,918,000 less 5,380,000 is 538,000 USD exactly, which is 0.1 of the base and no more.'),
  ('wellcost', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'A board pack reports the provision as ten percent of the approved total, and the fraction typed into the run was 0.1. What has gone wrong?', '["Nothing, because a fraction reads the same against either figure.", "The percentage was quoted against the wrong denominator, since 0.1 on the base is 0.09090909090909091 of the total.", "The fraction was applied twice, once to the base and once again to the total, which is what makes the two percentages agree.", "The pack has used the tangible fraction of 0.19516728624535315 by mistake."]'::jsonb, 1, 'If a reported share of the total equals the fraction that was typed, the wrong denominator was used somewhere.'),
  ('wellcost', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'A graduate hands you section rates in which the deepest section looks unusually cheap. Which mistake do you look for first?', '["A rig rate quoted per day rather than per hour.", "A bit cost left out of the numerator, which lowers a deep section more than a shallow one because it drills for longer.", "Dividing by the section total depth instead of by the interval that section actually drilled.", "Connection hours counted twice, which would flatter a long section most of all."]'::jsonb, 2, 'That substitution flatters the deepest and dearest section hardest, and nothing in the output errors or warns.'),
  ('wellcost', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'A vendor''s data sheet quotes a cost per metre with no interval and no hour terms shown behind it. What is your response?', '["Accept it, since a vendor quotes rates from its own records.", "Convert it to a section total by multiplying by your own interval, which makes the two figures comparable straight away.", "Compare it against the whole well figure of 1793.3333333333333 USD/m.", "Ask for the interval, the three hour terms and the pricing, because otherwise nobody can reproduce it."]'::jsonb, 3, 'The published 770 USD/m worked example is the standing reminder, since its 16 hour trip belongs to no section of this well.'),
  ('wellcost', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'Two engineers spend a whole review arguing about the rig dayrate when what they disagree on is the number of days. What is the habit?', '["Settle the rate first, since it is the contracted number.", "Split the difference between the two rates proposed and carry a larger provision, which covers the schedule disagreement as well.", "Move the line to a lump basis so the argument stops mattering.", "Name the exposure before arguing the rate, because 53.53 percent of this base moves with the days."]'::jsonb, 3, 'One extra day costs 160,000 USD on this well, and nobody can negotiate that after the well has been spudded.'),
  ('wellcost', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'A manager wants the provision deleted to bring the sheet under an approval threshold. What does deleting it actually change?', '["The risk carried rather than the cost, since nobody invoices a provision on a well that goes to plan.", "The base, which falls by the amount of the provision removed.", "The cost per metre of every section, because the provision is spread over the metres drilled before the sheet is totalled.", "The category split, since the provision sits inside the intangible subtotal."]'::jsonb, 0, 'The provision buys nothing. It is a statement about the other numbers, made in the same units as the numbers it doubts.'),
  ('wellcost', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'A review sorts the sheet by size and treats the top four numbers as the four things to control. What is wrong with the fourth?', '["Nothing, since the sort is by amount and the amount is real.", "It is a provision rather than a commitment, so it cannot be controlled the way a contract can.", "It is the mud and consumables line, which is priced on metres and therefore cannot be controlled once the hole has been designed.", "It is a tangible line, and tangible lines are settled by purchase order."]'::jsonb, 1, 'Sorting by size ranks commitment and uncertainty on one axis, and those two are not the same kind of number.'),
  ('wellcost', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'A finance manager asks when he will get a probability against the approved total. What is the honest answer?', '["Once the provision is raised to a defensible fraction.", "As soon as the cost time curve is drawn, because the shape of the curve gives the spread of outcomes around the base.", "Not from this tier, since the estimate must be rebuilt with ranges before a percentile can be read.", "Never, because a drilling estimate cannot be given a probability at all."]'::jsonb, 2, 'The case document already carries four ranged inputs, drawn 2000 times against a fixed seed, and this tier leaves them unused.'),
  ('wellcost', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'A colleague sketches cumulative cost against time and asks why his curve stops short of the approved total. What has he found?', '["The gap is exactly the provision, because it is attached to no activity and so never accrues.", "An error in his slopes, since the curve must reach the total.", "The lump items, which the curve places as steps at the end of the schedule rather than at the activity each one belongs to.", "The non-productive allowance, which the curve applies to time and not to money."]'::jsonb, 0, 'The curve ends on the base cost with an absolute error of zero across every combination that was tested.'),
  ('wellcost', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'A team proposes reporting the cost at the most likely inputs as the most likely cost of the well. Why is that not safe?', '["Because the most likely inputs are never the ones observed.", "Because a rig dayrate enters the cost through a division as well, which bends the relationship between its mean and its mode.", "Time goes as one over the rate of penetration, so the average time is not the time at the average rate.", "Because the provision is added after the inputs are chosen."]'::jsonb, 2, 'A rate that enters linearly passes its average straight through, and the gap from a nonlinear input runs one way rather than either way.'),
  ('wellcost', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'At the close of the tier a manager asks what you are now able to do with an AFE. What is the honest claim?', '["Predict the final well cost to within the provision carried.", "Build one from a schedule and defend where each line came from and what its provision covers.", "Rank any two wells against each other on cost per metre and say which of the two was drilled the more efficiently.", "Say which percentile of the outcome the approved total reaches."]'::jsonb, 1, 'When the money is spent, and how wrong the estimate might be, are the two questions the Expert tier takes up next.'),
  ('wellcost', 'intermediate', 'final', null, 1, 'A well closes out inside its approved figure although one vendor billed well above the amount shown beside its name. Is the authority in breach?', '["No, because the approval covers the total, and a single vendor running over inside that ceiling breaches nothing.", "Yes, since each named amount is authorised separately.", "Yes, because a document that describes the well accurately and still misprices one vendor has failed the test that defines it.", "No, because an authority is a forecast and a forecast is only wrong when the outcome differs from it."]'::jsonb, 0, 'Breach is defined by cover: the money authorised failing to reach the work authorised, which is a test on the ceiling.'),
  ('wellcost', 'intermediate', 'final', null, 2, 'A finance officer offers to sign the 5,380,000 USD now and release the provision later if the well needs it. Why is that not how the instrument works?', '["Because the provision has to be spent before the base can be.", "Because releasing it later would put the provision inside the intangible subtotal and unbalance the two category figures against the base.", "The signature is against 5,918,000 USD, and nobody approves a base cost and then finds the remainder afterwards.", "Because the engine cannot return a base without a fraction, so a sheet split that way would not price at all."]'::jsonb, 2, 'The engine returns the total as totalUsd, and that figure is the authority the reviewer is being asked to grant.'),
  ('wellcost', 'intermediate', 'final', null, 3, 'An estimator hands the cost run 16 days, taken from the 384 productive hours rather than the 432 elapsed ones. What appears on the sheet?', '["Nothing changes, since the allowance is applied inside the cost run.", "A rig line of 1,600,000 USD instead of 1,800,000 USD, with every other daily line short in the same proportion.", "A rig line of 1,800,000 USD still, because the engine restores the non productive stretch whenever the day count it is handed looks like a productive one.", "A rig line short by 200,000 USD and a mud line short by the same fraction, because both bases read the day count."]'::jsonb, 1, 'The rig is on hire during non productive time exactly as it is while drilling, which is why the elapsed figure is the one wanted.'),
  ('wellcost', 'intermediate', 'final', null, 4, 'The programme is revised so that a length of hole is drilled twice after a sidetrack, while the deepest point of the well is unchanged. Which lines respond?', '["No line responds, as neither quantity has moved.", "Every line responds, because a sidetrack changes the schedule and the schedule is what the whole sheet is priced against.", "The fixed price lines respond, because each of them names an activity and the activity list has grown.", "Only the footage lines, since they bill on the metres actually cut rather than on the depth the hole reaches."]'::jsonb, 3, 'Hand the engine a total depth where drilled length was wanted and every footage line comes out short without any error being raised.'),
  ('wellcost', 'intermediate', 'final', null, 5, 'A vendor is added to the sheet during a review. What is the least the engine will accept before it will price that new line?', '["A contract reference, a currency and a delivery date.", "A recognised basis, a recognised category, and either a rate or a value to suit whichever basis was chosen.", "A basis, a category, an amount and the activity the line attaches to, since a line with no activity cannot be placed on the curve at all.", "An amount and a category, because the basis can be inferred from whether the amount was quoted as a rate."]'::jsonb, 1, 'There is no default and no silent fallback, since a mistyped field would produce a plausible looking number rather than a visible failure.'),
  ('wellcost', 'intermediate', 'final', null, 6, 'The golden well runs two days long and drills 200 more metres than planned. Which of its eight priced lines are untouched by both events?', '["The two daily lines, since their rates are agreed in advance.", "Only the wellhead and the casing, because the tangible column is the part of the sheet that a schedule movement cannot reach.", "The five fixed price lines, which are multiplied by nothing and so hear neither the extra days nor the extra hole.", "None of them, because the provision moves and the provision is applied across every line on the sheet."]'::jsonb, 2, 'The provision moves anyway, since it is a fraction of a base that both events have enlarged.'),
  ('wellcost', 'intermediate', 'final', null, 7, 'An operator wants the same estimate repriced against a twenty day schedule. What has to be edited on the item list?', '["The rate on each daily line, scaled to the new schedule.", "Nothing whatever, because each line holds only a rate and the day count arrives from outside as an argument.", "Every line that names an activity, since the activity end times have moved and the amounts are read from those end times.", "The day count stored on each line, which is why the design keeps the count in one place per line."]'::jsonb, 1, 'If each line stored its own count there would be eighteen places to update and eighteen chances to miss one.'),
  ('wellcost', 'intermediate', 'final', null, 8, 'You judge the schedule to be this well''s principal risk, and a vendor will take 1,800,000 USD on any of the three bases. Which do you accept?', '["The daily basis, which is the most transparent to a reviewer.", "Whichever one is cheapest on the base case, given that a calibrated set of three prices identically at eighteen days.", "The footage basis alone, because it is the only one of the three that the engine will hold flat when the calendar moves.", "Either fixed price or footage, since their elasticity to elapsed days measures zero while the daily basis measures one."]'::jsonb, 3, 'All three agree to the dollar at eighteen days and three thousand metres, so the base case cannot tell you which was chosen.'),
  ('wellcost', 'intermediate', 'final', null, 9, 'Deepening the golden well to 4,000 m leaves the daily calibration billing 2,303,125 USD against the footage calibration''s 2,400,000 USD. What causes that order?', '["Extra metres add rotating hours only, while the day count also carries flat time that does not grow with depth.", "The footage rate was calibrated at a higher figure.", "The daily rate is capped once the well passes its planned total depth, so it cannot keep pace with a deepening beyond that point.", "Flat time falls away as a well deepens, so the elapsed day count grows more slowly than the metres do."]'::jsonb, 0, 'A line put on a daily basis to look cheap under a slip has quietly become the cheap one under a deepening.'),
  ('wellcost', 'intermediate', 'final', null, 10, 'Three extra days at 160,000 USD add 480,000 USD to the base. Set that against moving the fraction from 0.1 to 0.2, which takes the total to 6,456,000 USD. Which moves the approved figure further?', '["The slip, since it enlarges the provision as well as the base.", "The change of fraction, at 538,000 USD on the total, and it moves the figure without anything happening on the well.", "Neither, because the two are equal once the slip has been grossed up by the fraction that was applied to the base beneath it.", "The slip, because 480,000 USD of daily exposure outweighs a fraction that only ever touches the provision itself."]'::jsonb, 1, 'The slip does gross up, reaching 528,000 USD on the total, which leaves the two closer together than either party expects.'),
  ('wellcost', 'intermediate', 'final', null, 11, 'The rig is stood down two days waiting on weather and makes no hole at all. What bills through that period?', '["Nothing bills, because no activity was performed.", "The mud line bills at 150 USD per metre against the depth reached so far, since consumption continues while the hole is held.", "The rig alone at 100,000 USD per day, the spread being released whenever the well is not making progress.", "The rig and the spread together, at 160,000 USD of combined rate for each day of the stoppage."]'::jsonb, 3, 'This is why a well that stops making hole keeps making cost, and why the time allowance is a cost input rather than a scheduling curiosity.'),
  ('wellcost', 'intermediate', 'final', null, 12, 'Every daily and footage line on the golden happens to be intangible. Does that make the basis a usable guide to the category?', '["No, because a drill pipe purchase on a footage contract would be a footage line and tangible at the same time.", "Yes, since only fixed price lines can buy something durable.", "Yes on this sheet and on any sheet built the same way, because the two classifications are read from one another during validation.", "No, because the category is decided by the contract rather than by the object, and a contract can take any basis."]'::jsonb, 0, 'Three of the five fixed price lines are intangible as well, so neither direction of the shortcut survives contact with the sheet.'),
  ('wellcost', 'intermediate', 'final', null, 13, 'A day passes in the middle of the well during which the hole is cased and no rock is cut. Reading the cost curve across that day, which contributions slope?', '["All three slope, since every line accrues with time.", "None of them slope, because the depth curve is vertical while the hole is being cased and the cost curve follows the depth curve.", "The daily contribution slopes straight through, the footage contribution is horizontal, and a step lands when the run ends.", "The footage contribution slopes because casing is run over a measured length, and the daily contribution pauses."]'::jsonb, 2, 'The per day contribution is the only one on the sheet with no flat segments anywhere on the curve.'),
  ('wellcost', 'intermediate', 'final', null, 14, 'A contractor offers to convert the 60,000 USD per day spread into a fixed price agreed against the eighteen day schedule. What has the operator bought?', '["A cheaper line, worth 1,080,000 USD less than before.", "A change of category, because a fixed price is a purchase and a purchase buys something that stays in or on the well afterwards.", "Nothing at all, since a fixed price line and a daily line behave identically once the schedule has been agreed.", "The transfer of the schedule risk on that line, at an amount which today prices exactly as the daily version did."]'::jsonb, 3, 'Daily exposure would fall from 53.53 percent of the base, which is the figure worth quoting when the trade is argued.'),
  ('wellcost', 'intermediate', 'final', null, 15, 'A packer and tubing string are ordered for the golden well and priced as a line of their own. Where does that line land?', '["In the tangible column, because the hardware stays in the hole afterwards and can be recovered from it.", "In the intangible column, alongside the services line.", "In whichever column the completion services line already occupies, since a single vendor cannot be split across two categories.", "In neither, because hardware installed during a completion is carried outside the base as a separate capital item."]'::jsonb, 0, 'A real estimate splits that vendor into two lines for this reason, and the golden carries only the services half of it.'),
  ('wellcost', 'intermediate', 'final', null, 16, 'Two wells share a 5,380,000 USD base and divide it differently between the two columns. How can their after tax costs differ?', '["It cannot differ, since the base is the same figure.", "The larger tangible column carries a larger provision, because a fraction on the base falls more heavily on capitalised spend.", "Relief taken in the year of spend is worth more than relief spread over years, so the split reaches cash at different speeds.", "The engine holds a rate for each column and applies it, so two different splits return two different totals."]'::jsonb, 2, 'The engine holds no tax rates at all and only sorts the lines into the two buckets the fiscal calculation will ask for.'),
  ('wellcost', 'intermediate', 'final', null, 17, 'Handed the golden estimate ordered by amount and nothing else, what can a reader state, and what must he go back to the sheet for?', '["He can state everything except the approved total.", "He can state where the mass sits and how far the provision has climbed, but not the categories or the timing.", "He can state the categories, since an ordering by amount groups steel with steel and services with services before it sorts them.", "He can state the timing, because the largest amounts are the ones committed earliest in the schedule."]'::jsonb, 1, 'The wellhead lands early on the curve and the completion lands last, and an ordering by amount puts them four rows apart with no hint of it.'),
  ('wellcost', 'intermediate', 'final', null, 18, 'A manager proposes buying more casing than the well needs so that the tangible fraction reads better. What is the objection?', '["The engine would reject the extra steel as a negative value.", "It would move the provision, because a fraction on the base falls on tangible spend and would rise with the extra steel.", "It would not work, since additional casing is priced on a footage basis and the fraction is computed over the base.", "It produces a worse well at a higher cost with a more flattering ratio, and the ratio is an output rather than a target."]'::jsonb, 3, 'The other route to the same ratio, buying fewer days, is worth taking on its own merits at 160,000 USD each.'),
  ('wellcost', 'intermediate', 'final', null, 19, 'The three golden sections come to 1,674,000 USD between them, and neither the casing nor the wellhead appears in any of them. What does that say about the section form?', '["It never sees the tangible column at all, pricing only rig hours and a bit against the length a section cut.", "It sees the tangible column but not the intangible one.", "It sees both columns in proportion, which is why the section totals reach 0.31115241635687735 of the base cost of the well.", "It sees the tangible column only through the bit, which is the sole item in the form that survives the job."]'::jsonb, 0, 'The other two thirds are casing, cement, the wellhead, logging, mud, completion, the rig move and every hour the bit was off bottom.'),
  ('wellcost', 'intermediate', 'final', null, 20, 'A team carries the relief rule it applied in one country straight across to a well in another. Why is that unsafe?', '["Because the survival test itself changes between countries.", "The fiscal regime sets which costs qualify and how fast the rest is written down, and it varies by country and by contract.", "Because the engine stores a regime alongside each line and will refuse to price a line whose regime it does not recognise.", "Because the two columns are defined by the tax authority rather than by whether anything durable survives the job."]'::jsonb, 1, 'The engineering test gives you the classification, while the consequences of that classification are not yours to assume.'),
  ('wellcost', 'intermediate', 'final', null, 21, 'A joint venture partner has a cash call to fund and a set of books to keep. Which figures does each of those two jobs need?', '["Both need the base cost and nothing beyond it.", "The cash call needs the base and the books need the total, since a provision is funded only once it has actually been spent.", "The cash call is made against the total, while the books need the tangible and intangible subtotals to be separated.", "Both need the total, the split being an operational convenience with no reader outside the drilling team."]'::jsonb, 2, 'The drilling engineer reads the base and the total, which are the operational and the approval numbers respectively.'),
  ('wellcost', 'intermediate', 'final', null, 22, 'The well slips to 24 elapsed days, taking the base to 6,340,000 USD and the rig line to 2,400,000 USD. What happens to the fraction needed for the provision to overtake that rig line?', '["It rises, because the rig line grows with every day while a good part of the base is fixed and does not.", "It falls, since the base has grown and the provision with it.", "It holds at 0.3345724907063197, because that figure is a property of the engine rather than of any particular schedule.", "It holds, since both the rig line and the base are exposed to the schedule at exactly the same elasticity of one."]'::jsonb, 0, 'The crossing fraction is always the line''s own share of the base, so anything that moves that share moves the crossing.'),
  ('wellcost', 'intermediate', 'final', null, 23, 'A board pack states the provision as 9.09 percent. Which fraction was typed into the run that produced it?', '["A fraction of 0.0909, applied directly to the base cost.", "A fraction of 0.1, which becomes 0.09090909090909091 once the base has been enlarged by the provision itself.", "A fraction of 0.11111111111111111, being the reading that the non productive allowance reaches when it is taken against elapsed time.", "A fraction of 0.2, halved because the provision is quoted against a denominator that includes it."]'::jsonb, 1, 'Any percentage on an estimate should be read with the question of which of the two denominators produced it.'),
  ('wellcost', 'intermediate', 'final', null, 24, 'A partner asks that the provision be shown inside the intangible subtotal, most of the well being intangible anyway. What is wrong with that?', '["Nothing, provided the base is restated to match.", "The intangible subtotal is already the larger of the two, and a provision must be placed in the smaller one for the split to balance.", "It would break the closing check, since the two subtotals would then sum to the approved total rather than to the base.", "Nobody yet knows whether the provision will buy steel or days, so a category given in advance is a guess dressed as a classification."]'::jsonb, 3, 'The category shares add to one over the base, and the provision sits outside both of them by construction.'),
  ('wellcost', 'intermediate', 'final', null, 25, 'The fraction is raised from 0.1 to 0.15, a level many operators apply without argument. What does the ordering of the sheet do?', '["It is unchanged, the provision staying fourth throughout.", "The provision reaches 1,345,000 USD and stands second, above everything on the sheet except the rig line itself.", "The provision rises to 807,000 USD and passes the casing, standing third on a page of nine numbers.", "The provision drops below the completion services line, because raising a fraction lifts the base faster than it lifts the provision."]'::jsonb, 2, 'Between zero and a half the provision climbs the ordering from last place to first without any work being added to the well.'),
  ('wellcost', 'intermediate', 'final', null, 26, 'Three extra days add 480,000 USD to the base of the golden estimate. What does that do to the provision meant to absorb them?', '["It falls by a tenth, having been drawn down by the slip.", "It holds at 538,000 USD, since a provision is fixed at approval and the whole point of it is that a slip does not move it.", "It grows by the full 480,000 USD, the fraction being applied to the movement rather than to the base beneath it.", "It grows by a tenth of the slip, so the provision rode on the movement instead of covering it."]'::jsonb, 3, 'Raising the time allowance to 0.5 shows the same effect at scale, with 960,000 USD on the base and 96,000 USD on the provision.'),
  ('wellcost', 'intermediate', 'final', null, 27, 'Asked to defend a fraction of 0.1, an engineer answers that it is the corporate standard. Is that a defence?', '["It is an honest account of where the number came from, but it says nothing at all about this particular well.", "Yes, since a standard fraction is applied to every estimate.", "Yes, because a corporate standard is calibrated on outcomes and therefore carries a probability even when none is quoted.", "No, because a fraction chosen from precedent is applied to the total rather than to the base and is wrong before it is defended."]'::jsonb, 0, 'Precedent, the last well and a corporate standard are the three honest answers, and a fraction is a decision that looks like a calculation.'),
  ('wellcost', 'intermediate', 'final', null, 28, 'A firm purchase order for 800,000 USD of casing attracts the same provision as the rig. What would the model need before that could stop being flat?', '["A tangible exemption, which the engine already supports.", "A second base cost computed over the committed lines alone, which the engine forms whenever a line names an activity.", "A fraction per line rather than one over the base, and the item carries no field in which such a fraction could sit.", "Nothing at all, because the fraction already lands more lightly on lines whose price has been agreed in advance."]'::jsonb, 2, 'The model offers one fraction and applies it flat, making no attempt to defend a provision on a firm steel quote.'),
  ('wellcost', 'intermediate', 'final', null, 29, 'A bit costing 50,000 USD more than the one in the programme is offered at a rig rate of 6,000 USD per hour. How much time must it save to pay for itself?', '["Rather more than a full day, at twenty four hours.", "Something over eight hours, since the rig rate is what converts the extra price of a bit into hours of rig time.", "It cannot pay for itself on the form at all, because the bit sits above the line as a fixed cost while the hours sit inside a rate.", "About two hours, the bit being 0.06493506493506493 of the published rate and the rig the remainder of it."]'::jsonb, 1, 'This is the comparison the form was built for, and it is decided almost entirely by the hours saved rather than by the price paid.'),
  ('wellcost', 'intermediate', 'final', null, 30, 'The production section cuts 1,000 m at 10 m/hr, takes the flat allowance, and makes its round trip from 3,000 m at 500 m/hr. What are its three hour terms?', '["One hundred rotating hours, four on the flat allowance, and twelve for the round trip, giving 116 hours of rig time.", "Three hundred rotating, four flat and six on the trip.", "One hundred rotating hours, four on the allowance and sixteen on the trip, which is the hour set the published fixture carries.", "One hundred rotating hours, four flat and twenty four for the trip, the round trip factor being applied twice over."]'::jsonb, 0, 'Every hour in the form is productive, so none of the three carries the non productive allowance the schedule applies.'),
  ('wellcost', 'intermediate', 'final', null, 31, 'A colleague''s rate for the deepest section arrives at roughly a third of the figure you expected. Which substitution should you look for first?', '["The elapsed hours used where productive hours belonged.", "The section total depth used where the interval belonged, which divides the cost by three times the length actually cut.", "The bit cost omitted from the numerator, which on a deep section is a small enough share of the answer to pass unnoticed.", "The round trip factor left at one, halving the trip hours and with them a good part of the rig time above the line."]'::jsonb, 1, 'Nothing errors when it happens, and the number comes out most flattering on the deepest and most expensive section of the well.'),
  ('wellcost', 'intermediate', 'final', null, 32, 'The intermediate section is slowed from 15 to 12 m/hr while the production hole is held where it is. What do the two rankings do?', '["They continue to agree, both favouring the production hole.", "They part, but the other way about, the slower section becoming dearer by rate while remaining cheaper on its total spend.", "They part, the section reaching 581.3333333333334 USD/m and 872,000 USD, cheaper by rate and dearer by total.", "They cannot be compared once a rate of penetration has moved, because the pricing behind the two rankings is no longer identical."]'::jsonb, 2, 'The band runs from 9.027081243731192 to 14.423076923076923 m/hr, and the golden sits just above its upper edge.'),
  ('wellcost', 'intermediate', 'final', null, 33, 'You are asked what must be published beside a quoted rate before a reader can rebuild it. What is the list?', '["The interval and the section total depth behind it.", "The rate of penetration and the well it was drilled on, since a reader with those two can rebuild everything else from the programme.", "The section total, the base cost it belongs to and the share of that base which the sections between them account for.", "The interval, the three hour terms and the pricing, meaning the bit cost and the rig rate that were applied."]'::jsonb, 3, 'A rate quoted with no section attached is a number nobody can check, and the published fixture is the standing reminder of it.'),
  ('wellcost', 'intermediate', 'final', null, 34, 'A manager multiplies 1793.3333333333333 USD/m by the metres drilled and asks why the answer overshoots the three section totals so badly. What do you tell him?', '["The two figures share a denominator and not a numerator, the sections reaching only about a third of the base.", "The whole well rate was taken against the total, not the base.", "The section totals were divided by their intervals while the whole well rate divides by total depth, which on this well is a different length.", "The sections omit the non productive allowance, and restoring it to each of them closes the gap between the two figures."]'::jsonb, 0, 'Casing, cement, the wellhead, logging, mud, completion and the rig move sit outside the form entirely.'),
  ('wellcost', 'intermediate', 'final', null, 35, 'The bit is 0.24271844660194175 of the surface rate and 0.06702412868632708 of the production one. What does that do to a bit salesman''s argument in the two places?', '["It makes no difference, the rig dominating both sections.", "It reverses his argument, since the section where the bit is the smaller share is the section where its price matters most to the rate.", "On the shallow section his price is a quarter of the answer, while on the deep one he is selling hours and almost nothing else.", "It rules the shallow section out of the comparison, a bit share that large meaning the form is being used outside its range."]'::jsonb, 2, 'The same bit price is therefore a different argument in the two places, which the single ratio on the published fixture conceals.'),
  ('wellcost', 'intermediate', 'final', null, 36, 'A footage line has been priced against total depth rather than metres drilled. Which of the four closing checks catches it?', '["The check that the subtotals sum to the base cost.", "The check that every rate per metre comes from the hours of its own section, which is the check written to catch exactly this class of error.", "The check on the denominator behind the provision, since a footage line priced short changes the share the provision reaches.", "None of them, because the subtotals still sum, the difference is still the provision and the share is still correct."]'::jsonb, 3, 'The same is true of a daily line priced on productive days, which is why the two habits matter more than the checks do.'),
  ('wellcost', 'intermediate', 'final', null, 37, 'You have sixty seconds with an estimate you have never seen. Which two readings do you take first?', '["What share of the base bills daily, and how far up the ordering by amount the provision has climbed.", "The tangible fraction and the cost per metre of the deepest hole.", "The approved total and the number of priced lines behind it, since those two settle whether the sheet has been built line by line at all.", "The largest line and its category, which together say whether the well is a purchase of steel or a purchase of services."]'::jsonb, 0, 'On the golden those two readings give 53.53 percent daily and a provision standing fourth, which frames every later question.'),
  ('wellcost', 'intermediate', 'final', null, 38, 'The well is expected to run two days long. What can you produce at once, and what can you still not produce?', '["Both, since the schedule and the fraction are known.", "Neither, because a movement in the schedule has to be rebuilt through the activity programme before any line can be repriced from it.", "The cost of each day and the lines that pay it, but no statement at all about how likely the total is to hold.", "The probability the total holds, but not the cost of the days, which depends on which activities the slip lands in."]'::jsonb, 2, 'Ranges rather than single inputs are what the question needs, and this tier can say exactly what is missing without supplying it.'),
  ('wellcost', 'intermediate', 'final', null, 39, 'A day of waiting on weather cost 160,000 USD and made no hole whatever. What is that day''s cost per metre?', '["There is none, since the form refuses an interval of zero and a flat spot has a cost without having a rate.", "It is 160,000 USD per metre, the day having cut one metre or less.", "It is the whole well figure of 1793.3333333333333 USD/m, which is the rate any period of a well defaults to when it makes no hole of its own.", "It is zero, because the numerator of the form counts only rig hours that were spent making hole."]'::jsonb, 0, 'The guard on the denominator is strict for that reason, rather than returning a very large number and letting it be quoted.'),
  ('wellcost', 'intermediate', 'final', null, 40, 'Somebody proposes accruing the provision along the cost curve in proportion to time so that the curve ends on the approved figure. What is wrong with it?', '["Nothing, provided the fraction is applied at each step.", "The provision attaches to no activity, so it accrues nowhere and the curve is built to end on the base instead.", "The curve already ends on the approved figure, so spreading the provision along it would carry the last point above the authority granted.", "The provision would have to accrue against metres rather than time, the base being a mixture of daily and footage exposure."]'::jsonb, 1, 'The curve lands on the base with an absolute error of zero, so the gap to the total is always exactly the provision and nothing else.'),
  ('wellcost', 'intermediate', 'final', null, 41, 'The capstone runs on conditions of its own rather than on the golden well. What carries across from this tier?', '["The golden schedule, which every capstone is priced against.", "The base cost and the provision, since a capstone varies the programme while holding the priced item list exactly where it was.", "The published rate of 770 USD/m, which is the one figure in the course built to be carried between wells.", "The order of the work and the four checks at the end of it, and none of the golden figures themselves."]'::jsonb, 3, 'Each step needs the one before it, which is why the order is not negotiable even when every input has changed.'),
  ('wellcost', 'intermediate', 'final', null, 42, 'An estimate arrives in which every line has been put on a fixed price basis to keep the sheet tidy. What has been destroyed?', '["The category split, fixed price lines all being tangible.", "The cost curve, because a sheet of fixed price lines produces steps only and a curve needs at least one sloping contribution to be drawn.", "The ability to reprice it, since elasticity to elapsed days is now zero throughout and a slip appears to cost nothing.", "The provision, which cannot be computed once no line on the sheet is exposed to the schedule that produced the day count."]'::jsonb, 2, 'Converting a line to a different basis to make it tidier is the one instruction the working order rules out explicitly.');
